def sum_of_factorials_optimized(n: int) -> int:
    if n < 1 or n > 50:
        raise ValueError("n must be between 1 and 50, inclusive")

    current_factorial = 1
    factorial_sum = 0

    for i in range(1, n + 1):
        current_factorial *= i
        factorial_sum += current_factorial

    return factorial_sum

def cantor_numbering(N: int) -> str:
    level = 1
    while N > level:
        N -= level
        level += 1
    if level % 2 == 0:
        numerator = N
        denominator = level - N + 1
    else:
        numerator = level - N + 1
        denominator = N
    return f"{numerator}/{denominator}"

def max_product(num_str: str, N: int, K: int) -> int:
    def helper(start, k):
        if k == 0:
            return int(num_str[start:])
        max_val = 0
        for end in range(start + 1, N - k + 1):
            left = int(num_str[start:end])
            right = helper(end, k - 1)
            max_val = max(max_val, left * right)
        return max_val

    return helper(0, K)

