def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    row_counts = [0] * (M + 1)
    col_counts = [0] * (N + 1)

    for (Xi, Yi, Pi, Qi) in chatting_pairs:
        if Xi == Pi:
            row_counts[min(Yi, Qi)] += 1
        elif Yi == Qi:
            col_counts[min(Xi, Pi)] += 1

    best_rows = sorted(range(1, M), key=lambda x: row_counts[x], reverse=True)[:K]
    best_cols = sorted(range(1, N), key=lambda x: col_counts[x], reverse=True)[:L]

    return (' '.join(map(str, sorted(best_rows))), ' '.join(map(str, sorted(best_cols))))

def count_passing_ways(n: int, m: int) -> int:
    if n == 0 or m == 0:
        return 0
    if n == 1:
        return 1 if m % 2 == 0 else 0

    dp = [[0] * n for _ in range(m + 1)]
    dp[0][0] = 1

    for k in range(1, m + 1):
        for i in range(n):
            dp[k][i] = dp[k-1][(i-1) % n] + dp[k-1][(i+1) % n]

    return dp[m][0]

