def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    dp = [0] * (n + 1)
    for price, importance in items:
        for budget in range(n, price - 1, -1):
            dp[budget] = max(dp[budget], dp[budget - price] + price * importance)
    return dp[n]

def max_energy(beads):
    n = len(beads)
    beads = beads + beads[:-1]  # Duplicate the list to handle circular nature
    dp = [[0] * (2 * n) for _ in range(2 * n)]

    for length in range(2, n + 1):
        for i in range(n):
            j = i + length - 1
            for k in range(i + 1, j + 1):
                dp[i][j] = max(dp[i][j], dp[i][k] + dp[k][j] + beads[i] * beads[k] * beads[j + 1])

    return max(dp[i][i + n - 1] for i in range(n))

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    terms = []
    for i, coeff in enumerate(coeffs):
        degree = n - i
        if coeff == 0:
            continue
        sign = '+' if coeff > 0 else '-'
        if len(terms) == 0 and coeff > 0:
            sign = ''
        abs_coeff = abs(coeff)
        if abs_coeff == 1 and degree != 0:
            abs_coeff_str = ''
        else:
            abs_coeff_str = str(abs_coeff)
        if degree > 1:
            term_str = f'{abs_coeff_str}x^{degree}'
        elif degree == 1:
            term_str = f'{abs_coeff_str}x'
        else:
            term_str = str(abs_coeff)
        terms.append(sign + term_str)
    return ''.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for e, o in zip(encoded, original):
        if e in mapping:
            if mapping[e] != o:
                return "Failed"
        else:
            mapping[e] = o

    if len(mapping) < 26:
        return "Failed"

    decoded_message = []
    for char in message:
        if char in mapping:
            decoded_message.append(mapping[char])
        else:
            return "Failed"

    return ''.join(decoded_message)

def largest_prime_factor(n: int) -> int:
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return n // i
    return n

def count_partitions(n: int, k: int, x: int) -> int:
    if n < k * x:
        return 0
    if k == 1:
        return 1 if n >= x else 0
    res = 0
    for i in range(x, n - k * x + 1):
        res += count_partitions(n - i, k - 1, i)
    return res

def count_sequences(n: int, last: int, memo: dict) -> int:
    if last < 1:
        return 0
    if last in memo:
        return memo[last]
    count = 1  # Count the sequence consisting of the number itself
    for i in range(1, last // 2 + 1):
        count += count_sequences(n, i, memo)
    memo[last] = count
    return count

def count_coprime_pairs(x0: int, y0: int) -> int:
    from math import gcd
    count = 0
    if y0 % x0 != 0:
        return 0
    quotient = y0 // x0
    for a in range(1, int(quotient**0.5) + 1):
        if quotient % a == 0:
            b = quotient // a
            if gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    from collections import deque

    if A == B:
        return 0

    queue = deque([(A, 0)])
    visited = set([A])

    while queue:
        current, steps = queue.popleft()

        if steps >= 10:
            continue

        for src, tgt in rules:
            start = 0
            while start <= len(current) - len(src):
                pos = current.find(src, start)
                if pos != -1:
                    new_string = current[:pos] + tgt + current[pos + len(src):]
                    if new_string == B:
                        return steps + 1
                    if new_string not in visited:
                        visited.add(new_string)
                        queue.append((new_string, steps + 1))
                else:
                    break
                start = pos + 1

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    from collections import deque

    # Convert the number to a string to facilitate digit manipulation
    original_str = str(n)
    queue = deque([original_str])
    visited = set([original_str])

    while queue:
        current = queue.popleft()

        # Try to apply each rule to each digit in the current number
        for i in range(len(current)):
            for x, y in rules:
                if current[i] == str(x):
                    # Generate a new number by applying the transformation rule
                    new_number = current[:i] + str(y) + current[i+1:]
                    if new_number not in visited:
                        visited.add(new_number)
                        queue.append(new_number)

    # Return the count of unique numbers generated
    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    for participant, participant_statements in statements.items():
        for statement in participant_statements:
            if any(day in statement for day in days_of_week):
                continue
            if participant in liar_count:
                # Liar's statement should be false in this scenario
                if (statement == f"{scenario} is guilty." and scenario != participant) or \
                   (statement == f"{scenario} is not guilty." and scenario == participant):
                    break
            else:
                # Truth-teller's statement should be true in this scenario
                if (statement == f"{scenario} is guilty." and scenario == participant) or \
                   (statement == f"{scenario} is not guilty." and scenario != participant):
                    break
        else:
            # If we didn't break, the current participant's statements are inconsistent with the scenario
            return False
    return True

