    opponent_score = 0

    for point in points:
        if point == 'W':
            player_score += 1
        elif point == 'L':
            opponent_score += 1

        if (player_score >= system or opponent_score >= system) and abs(player_score - opponent_score) >= 2:
            scores.append(f"{player_score}:{opponent_score}")
            player_score = 0
            opponent_score = 0

    if player_score > 0 or opponent_score > 0:
        scores.append(f"{player_score}:{opponent_score}")

    return scores

def catalan_number(n: int) -> int:
    if n < 0:
        raise ValueError("n must be non-negative")
    catalan = [0] * (n + 1)
    catalan[0] = 1
    for i in range(1, n + 1):
        for j in range(i):
            catalan[i] += catalan[j] * catalan[i - j - 1]
    return catalan[n]

