def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    dp = [False] * (V + 1)
    dp[0] = True

    for volume in volumes:
        for j in range(V, volume - 1, -1):
            if dp[j - volume]:
                dp[j] = True

    max_occupied = 0
    for i in range(V, -1, -1):
        if dp[i]:
            max_occupied = i
            break

    return V - max_occupied

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(m + 1):
            dp[i][j] = dp[i - 1][j]
            for k in range(1, min(a[i - 1], j) + 1):
                dp[i][j] = (dp[i][j] + dp[i - 1][j - k]) % MOD

    return dp[n][m]

def mod_inverse(a, b):
    def extended_gcd(aa, bb):
        if aa == 0:
            return bb, 0, 1
        gcd, x1, y1 = extended_gcd(bb % aa, aa)
        x = y1 - (bb // aa) * x1
        y = x1
        return gcd, x, y

    gcd, x, _ = extended_gcd(a, b)
    if gcd != 1:
        return None
    else:
        return x % b

