def minimum_students_to_leave(heights):
    n = len(heights)
    if n < 3:
        return 0

    # increasing[i] stores the length of the longest increasing subsequence ending at i
    increasing = [1] * n
    for i in range(1, n):
        for j in range(i):
            if heights[i] > heights[j]:
                increasing[i] = max(increasing[i], increasing[j] + 1)

    # decreasing[i] stores the length of the longest decreasing subsequence starting at i
    decreasing = [1] * n
    for i in range(n - 2, -1, -1):
        for j in range(i + 1, n):
            if heights[i] > heights[j]:
                decreasing[i] = max(decreasing[i], decreasing[j] + 1)

    # Calculate the minimum number of students to remove
    min_remove = n
    for i in range(n):
        # The length of the formation if we use heights[i] as the peak
        formation_length = increasing[i] + decreasing[i] - 1
        min_remove = min(min_remove, n - formation_length)

    return min_remove

def min_groups(w, n, prices):
    prices.sort()
    left, right = 0, n - 1
    groups = 0

    while left <= right:
        if prices[left] + prices[right] <= w:
            left += 1
        right -= 1
        groups += 1

    return groups

def hanoi_double_iterative(n: int) -> int:
    if n == 0:
        return 0
    moves = 2
    for i in range(1, n):
        moves = 3 * moves + 2
    return moves
